/* Exact jam counts on the 2×W torus (W ≤ 32) over configurations with NO plug column and at
 * least W east cars: the only plug-free configurations that can jam (bml.thin, Lemma 2).
 *
 * A configuration is a cyclic word of W column states (8 letters: (row0,row1) ∈ {0,E,N}² minus
 * (N,N)). Translations along the torus rotate the word, and jam status and car counts are
 * translation-invariant. So each rotation class is visited once, as a necklace generated by the
 * Fredricksen–Kessler–Maiorana algorithm, and weighted by its number of distinct rotations
 * (the period of its Lyndon root). Branches that cannot reach W east cars are cut.
 * Each necklace is classified exactly by Floyd cycle detection on the full torus (CLASSIC rule).
 *
 * Output: one line per car count n = 0 … 2W, "n jams visited_states" (both orbit-weighted).
 * usage: noplug_jam W
 */
#include <stdint.h>
#include <stdio.h>
#include <stdlib.h>

static int W;
static uint32_t FULL;
typedef struct { uint32_t e0, e1, n0, n1; } S;

static inline uint32_t rotl1(uint32_t m) { return ((m << 1) | (m >> (W - 1))) & FULL; }   /* +x */
static inline uint32_t rotr1(uint32_t m) { return ((m >> 1) | (m << (W - 1))) & FULL; }   /* -x */
static inline S step(S s) {
    uint32_t o0 = s.e0 | s.n0, o1 = s.e1 | s.n1;
    uint32_t m0 = s.e0 & ~rotr1(o0), m1 = s.e1 & ~rotr1(o1);
    s.e0 = (s.e0 & ~m0) | rotl1(m0);
    s.e1 = (s.e1 & ~m1) | rotl1(m1);
    o0 = s.e0 | s.n0; o1 = s.e1 | s.n1;
    uint32_t a = s.n0 & ~o1, b = s.n1 & ~o0;
    s.n0 = (s.n0 & ~a) | b;
    s.n1 = (s.n1 & ~b) | a;
    return s;
}
static inline int eq(S a, S b) { return a.e0 == b.e0 && a.e1 == b.e1 && a.n0 == b.n0 && a.n1 == b.n1; }
static int jams(S s) {
    S slow = step(s), fast = step(slow);
    while (!eq(slow, fast)) { slow = step(slow); fast = step(step(fast)); }
    return eq(step(slow), slow);
}

static const int C0[8] = {0, 1, 2, 0, 1, 2, 0, 1};
static const int C1[8] = {0, 0, 0, 1, 1, 1, 2, 2};
static const int NE[8] = {0, 1, 0, 1, 2, 1, 0, 1};
static const int NC[8] = {0, 1, 1, 1, 2, 2, 1, 2};

typedef struct { uint64_t jam[65], seen[65]; } Acc;

static void leaf(const int *a, int period, Acc *acc) {
    S s = {0, 0, 0, 0};
    int cars = 0;
    for (int x = 0; x < W; x++) {
        int v = a[x + 1];
        if (C0[v] == 1) s.e0 |= 1u << x; else if (C0[v] == 2) s.n0 |= 1u << x;
        if (C1[v] == 1) s.e1 |= 1u << x; else if (C1[v] == 2) s.n1 |= 1u << x;
        cars += NC[v];
    }
    acc->seen[cars] += period;
    if (jams(s)) acc->jam[cars] += period;
}

/* FKM: a[1..t-1] is a prenecklace with Lyndon-prefix period p; e = east cars so far. */
static void gen(int *a, int t, int p, int e, Acc *acc) {
    if (e + 2 * (W - t + 1) < W) return;
    if (t > W) { if (W % p == 0) leaf(a, p, acc); return; }
    a[t] = a[t - p];
    gen(a, t + 1, p, e + NE[a[t]], acc);
    for (int j = a[t - p] + 1; j < 8; j++) { a[t] = j; gen(a, t + 1, t, e + NE[j], acc); }
}

/* Collect the frames at depth D (t = D + 1) for parallel processing. */
typedef struct { int a[8]; int p, e; } Frame;
static Frame *frames; static int nframes, cap;
static void collect(int *a, int t, int p, int e, int D) {
    if (e + 2 * (W - t + 1) < W) return;
    if (t > D) {
        if (nframes == cap) { cap = cap ? 2 * cap : 1024; frames = realloc(frames, cap * sizeof(Frame)); }
        Frame f; for (int i = 0; i <= D; i++) f.a[i] = a[i]; f.p = p; f.e = e; frames[nframes++] = f;
        return;
    }
    a[t] = a[t - p];
    collect(a, t + 1, p, e + NE[a[t]], D);
    for (int j = a[t - p] + 1; j < 8; j++) { a[t] = j; collect(a, t + 1, t, e + NE[j], D); }
}

int main(int argc, char **argv) {
    W = atoi(argv[1]);
    FULL = (W == 32) ? ~0u : ((1u << W) - 1);
    int D = W < 5 ? W : 5;
    int a0[34] = {0};
    collect(a0, 1, 1, 0, D);
    static Acc total;
    #pragma omp parallel
    {
        Acc acc = {{0}, {0}};
        int a[34];
        #pragma omp for schedule(dynamic, 1)
        for (int i = 0; i < nframes; i++) {
            a[0] = 0;
            for (int k = 1; k <= D; k++) a[k] = frames[i].a[k];
            if (D == W) { if (W % frames[i].p == 0) leaf(a, frames[i].p, &acc); }
            else gen(a, D + 1, frames[i].p, frames[i].e, &acc);
        }
        #pragma omp critical
        for (int n = 0; n <= 2 * W; n++) { total.jam[n] += acc.jam[n]; total.seen[n] += acc.seen[n]; }
    }
    for (int n = 0; n <= 2 * W; n++)
        printf("%d %llu %llu\n", n, (unsigned long long)total.jam[n], (unsigned long long)total.seen[n]);
    return 0;
}
